mapper.select:
SELECT EXISTS (
    SELECT 1 FROM transport_trip
    WHERE schedule_id = #{scheduleId} AND scheduled_departure_at = #{scheduledDepartureAt}
)

SELECT id, trip_code, schedule_id, from_hub_id, to_hub_id, vehicle_id,
       scheduled_departure_at, planned_arrival_at, estimated_arrival_at,
       actual_departure_at, actual_arrival_at, capacity_weight, reserved_weight,
       status, created_at, updated_at
FROM transport_trip
WHERE 1 = 1

    AND from_hub_id = #{fromHubId}


    AND to_hub_id = #{toHubId}


    AND scheduled_departure_at >= #{departureFrom}


    AND scheduled_departure_at <= #{departureTo}

ORDER BY scheduled_departure_at ASC
